export default async function ingest({ events }, ctx) {
  let s = (await ctx.state.get("phishing-mail")) || {
    queue: [],
    seen: [],
    pending: null,
    phase: "item",
  };
  for (const e of events) {
    if (!e.messageId) throw Error("Message ID missing");
    if (!s.seen.includes(e.messageId) && !s.queue.some((x) => x.messageId === e.messageId))
      s.queue.push(e);
  }
  await ctx.state.set("phishing-mail", s);
  return { ok: true };
}

