export default async function next(
  { acknowledge, resolution, confirmedValue, projectKey, issueType, relayUrl },
  ctx,
) {
  let s = await ctx.state.get("phishing-mail");
  if (!s) throw Error("Missing queue");
  if (!projectKey || projectKey.includes("YOUR_") || !issueType || !/^https:\/\//.test(relayUrl))
    throw Error("Configure Jira project, issue type and attachment relay");
  if (s.pending) {
    if (acknowledge !== s.pending || !["absent", "confirmed"].includes(resolution))
      throw Error("Inspect unknown write " + s.pending);
    if (resolution === "confirmed") {
      if (s.phase === "screenshot") {
        if (!/^https:\/\//.test(confirmedValue)) throw Error("Enter confirmed screenshot URL");
        s.imageUrl = confirmedValue;
        s.phase = "analyze";
      } else if (s.phase === "issue") {
        if (!confirmedValue) throw Error("Enter confirmed Jira issue key");
        s.issueKey = confirmedValue;
        s.phase = "attach";
      } else if (s.phase === "attach") {
        s.seen.push(s.queue[0].messageId);
        s.queue.shift();
        s.phase = "item";
      }
    }
    s.pending = null;
    await ctx.state.set("phishing-mail", s);
  }
  let e = s.queue[0];
  if (!e)
    return {
      action: "done",
      messageId: ".",
      html: ".",
      url: "",
      body: {},
      summary: ".",
      description: ".",
      projectKey,
      issueType,
    };
  if (s.phase === "item") {
    s.phase = "fetch";
    await ctx.state.set("phishing-mail", s);
  }
  let action = s.phase,
    url = "",
    body = {},
    html = s.html || ".",
    summary = ".",
    description = ".";
  if (action === "screenshot") {
    s.pending = "screenshot:" + e.messageId;
    await ctx.state.set("phishing-mail", s);
  }
  if (action === "analyze") {
    url = "https://api.openai.com/v1/chat/completions";
    body = {
      model: "gpt-4o-mini",
      messages: [
        {
          role: "system",
          content:
            "Assess phishing risk. Return JSON with malicious boolean and summary string, explaining your reasoning.",
        },
        {
          role: "user",
          content: "HTML body: " + s.html + "\nHeaders: " + JSON.stringify(s.headers),
        },
      ],
      response_format: { type: "json_object" },
    };
  }
  if (action === "issue") {
    summary =
      (s.malicious ? "Potentially Malicious" : "Potentially Benign") +
      ' - Phishing Email Reported: "' +
      s.subject +
      '"';
    description =
      "Reported by " +
      s.recipient +
      "\nSubject: " +
      s.subject +
      "\n\n" +
      s.text +
      "\n\nAnalysis:\n" +
      s.analysis;
    s.pending = "issue:" + e.messageId;
    await ctx.state.set("phishing-mail", s);
  }
  if (action === "attach") {
    url = relayUrl;
    body = { issueKey: s.issueKey, imageUrl: s.imageUrl, messageId: e.messageId, text: s.text };
    s.pending = "attach:" + e.messageId;
    await ctx.state.set("phishing-mail", s);
  }
  return {
    action,
    messageId: e.messageId,
    html,
    url,
    body,
    summary,
    description,
    projectKey,
    issueType,
  };
}

