import { Buffer } from "node:buffer";
async function result(
  { kind, payload, messageText, subject, to, imageUrl, statusCode, body, issue },
  ctx,
) {
  let s = await ctx.state.get("phishing-mail");
  if (!s?.queue?.length) throw Error("Missing mail state");
  if (kind === "fetch") {
    if (!payload || !Array.isArray(payload.headers)) throw Error("Missing full Gmail payload");
    const walk = (p) => {
      if (p?.mimeType === "text/html" && p.body?.data)
        return Buffer.from(p.body.data.replace(/-/g, "+").replace(/_/g, "/"), "base64").toString(
          "utf8",
        );
      for (const c of p?.parts || []) {
        const r = walk(c);
        if (r) return r;
      }
      return "";
    };
    s.html = walk(payload);
    if (!s.html) throw Error("Email has no HTML body");
    s.headers = payload.headers;
    s.text = messageText;
    s.subject = subject;
    s.recipient = to;
    s.phase = "screenshot";
  }
  if (kind === "screenshot") {
    if (!/^https:\/\//.test(imageUrl)) throw Error("Screenshot result unknown");
    s.imageUrl = imageUrl;
    s.pending = null;
    s.phase = "analyze";
  }
  if (kind === "analyze") {
    if (statusCode !== 200 || typeof body?.choices?.[0]?.message?.content !== "string")
      throw Error("Vision analysis failed");
    const v = JSON.parse(body.choices[0].message.content);
    if (typeof v.malicious !== "boolean" || typeof v.summary !== "string" || !v.summary)
      throw Error("Invalid phishing classification");
    s.malicious = v.malicious;
    s.analysis = v.summary;
    s.phase = "issue";
  }
  if (kind === "issue") {
    if (!issue?.key) throw Error("Jira creation result unknown");
    s.issueKey = issue.key;
    s.pending = null;
    s.phase = "attach";
  }
  if (kind === "attach") {
    if (statusCode !== 200 || body?.ok !== true) throw Error("Attachment result unknown");
    s.pending = null;
    s.seen.push(s.queue[0].messageId);
    s.queue.shift();
    s.phase = "item";
    delete s.imageUrl;
    delete s.issueKey;
    delete s.html;
    delete s.text;
    delete s.headers;
    delete s.analysis;
  }
  await ctx.state.set("phishing-mail", s);
  return { ok: true };
}

export default async function run(input, ctx) {
  return result({ ...input, kind: "fetch" }, ctx);
}

